"""Evaluate retrieval, with a four-way ablation.

The point of this module is to make the claim "hybrid retrieval helps"
falsifiable. Four arms run over an identical query set and identical corpus:

    bm25           lexical only
    dense          embeddings only
    hybrid         both, fused with reciprocal rank fusion
    hybrid_rerank  fused, then re-ordered by a cross-encoder

**Query construction.** Queries are generated by a model from held-out
passages, with an explicit instruction not to reuse distinctive tokens from
the passage. This matters: if queries copy rare strings, BM25 wins by
construction and the comparison is meaningless. Generated queries are cached
to `fixtures/retrieval_queries.json` so the numbers are reproducible without
re-running generation, and so they can be inspected by hand.

**Relevance.** A hit counts if it comes from the document the query was
generated from. This is known-item retrieval — it under-counts genuinely
relevant results from other documents, so absolute recall is a lower bound.
It is applied identically to every arm, so the comparison between arms is
still fair.
"""
from __future__ import annotations

import json
import math
import random
import time
from dataclasses import asdict, dataclass
from pathlib import Path

from pydantic import BaseModel
from rich.console import Console
from rich.progress import Progress
from rich.table import Table

from bountybrain.clients.llm import load_prompt, structured_many
from bountybrain.config import settings
from bountybrain.rag import hybrid
from bountybrain.rag.index import load_chunk_cache

console = Console()

FIXTURE = Path(__file__).resolve().parents[1] / "fixtures" / "retrieval_queries.json"
SYSTEM = "You write concise, realistic search queries. You answer only with JSON."


class GeneratedQuery(BaseModel):
    query: str = ""
    usable: bool = True


@dataclass
class EvalQuery:
    query: str
    document_id: int
    chunk_idx: int
    title: str
    doc_type: str
    url: str


# --------------------------------------------------------------------------
# query set
# --------------------------------------------------------------------------


def generate_queries(
    n: int = 200,
    seed: int = 23,
    min_chars: int = 400,
    concurrency: int | None = None,
) -> list[EvalQuery]:
    """Sample chunks stratified by document type and generate one query each."""
    rows = [r for r in load_chunk_cache() if len(r.get("text", "")) >= min_chars]
    if not rows:
        raise RuntimeError("No chunk cache — run `python index_corpus.py` first.")

    by_type: dict[str, list[dict]] = {}
    for r in rows:
        by_type.setdefault(r.get("doc_type", "unknown"), []).append(r)

    rng = random.Random(seed)
    per_type = max(1, n // max(1, len(by_type)))
    sample: list[dict] = []
    for _doc_type, items in sorted(by_type.items()):
        rng.shuffle(items)
        sample.extend(items[:per_type])
    rng.shuffle(sample)
    sample = sample[:n]

    requests = [
        (
            SYSTEM,
            load_prompt(
                "generate_query",
                title=r.get("title", "")[:200],
                passage=r.get("text", "")[:2500],
            ),
        )
        for r in sample
    ]

    with Progress(console=console) as progress:
        task = progress.add_task("generating queries", total=len(requests))
        replies = structured_many(
            GeneratedQuery,
            requests,
            max_tokens=128,
            concurrency=concurrency,
            progress_cb=lambda done: progress.update(task, completed=done),
        )

    out: list[EvalQuery] = []
    for row, reply in zip(sample, replies, strict=True):
        if reply is None or not reply.usable or not reply.query.strip():
            continue
        out.append(
            EvalQuery(
                query=reply.query.strip(),
                document_id=row["document_id"],
                chunk_idx=row.get("chunk_idx", 0),
                title=row.get("title", ""),
                doc_type=row.get("doc_type", ""),
                url=row.get("url", ""),
            )
        )
    return out


def save_queries(queries: list[EvalQuery], path: Path | None = None) -> Path:
    out = path or FIXTURE
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(json.dumps([asdict(q) for q in queries], indent=2))
    return out


def load_queries(path: Path | None = None) -> list[EvalQuery]:
    src = path or FIXTURE
    if not src.exists():
        return []
    return [EvalQuery(**q) for q in json.loads(src.read_text())]


# --------------------------------------------------------------------------
# metrics
# --------------------------------------------------------------------------


def _dcg(relevances: list[int]) -> float:
    return sum(rel / math.log2(i + 2) for i, rel in enumerate(relevances))


def evaluate_mode(
    queries: list[EvalQuery], mode: str, top_k: int = 10, candidates: int = 40
) -> dict:
    ranks: list[int | None] = []
    ndcgs: list[float] = []
    latencies: list[float] = []

    for q in queries:
        t0 = time.perf_counter()
        result = hybrid.search(q.query, top_k=top_k, mode=mode, candidates=candidates)
        latencies.append((time.perf_counter() - t0) * 1000)

        rank = None
        rels = []
        for i, hit in enumerate(result.hits, start=1):
            hit_is_gold = hit.document_id == q.document_id
            rels.append(1 if hit_is_gold else 0)
            if hit_is_gold and rank is None:
                rank = i
        ranks.append(rank)
        # ideal ranking puts the single gold document first
        ndcgs.append(_dcg(rels) / _dcg([1]) if rels else 0.0)

    n = len(queries)

    def recall_at(k: int) -> float:
        return sum(1 for r in ranks if r is not None and r <= k) / n if n else 0.0

    mrr = sum(1.0 / r for r in ranks if r is not None) / n if n else 0.0
    latencies.sort()
    return {
        "mode": mode,
        "n": n,
        "recall@1": round(recall_at(1), 4),
        "recall@5": round(recall_at(5), 4),
        "recall@10": round(recall_at(10), 4),
        "mrr": round(mrr, 4),
        "ndcg@10": round(sum(ndcgs) / n, 4) if n else 0.0,
        "median_latency_ms": round(latencies[len(latencies) // 2], 1) if latencies else 0.0,
        "p95_latency_ms": round(latencies[int(len(latencies) * 0.95)], 1) if latencies else 0.0,
    }


def evaluate(
    modes: list[str] | None = None,
    top_k: int = 10,
    queries: list[EvalQuery] | None = None,
    breakdown: bool = True,
) -> dict:
    qs = queries if queries is not None else load_queries()
    if not qs:
        raise RuntimeError(
            "No evaluation queries. Run `python eval.py --generate-queries` first."
        )

    available = hybrid.available_modes()
    modes = modes or list(hybrid.MODES)
    runnable = [m for m in modes if m in available]
    skipped = [m for m in modes if m not in available]
    if skipped:
        console.print(
            f"[yellow]Skipping {', '.join(skipped)} — vector store empty or unavailable.[/yellow]"
        )

    results: dict = {"queries": len(qs), "modes": {}, "skipped_modes": skipped}
    for mode in runnable:
        console.print(f"[cyan]evaluating {mode}…[/cyan]")
        results["modes"][mode] = evaluate_mode(qs, mode, top_k=top_k)

    if breakdown and runnable:
        best = "hybrid_rerank" if "hybrid_rerank" in runnable else runnable[-1]
        by_type: dict[str, list[EvalQuery]] = {}
        for q in qs:
            by_type.setdefault(q.doc_type, []).append(q)
        results["by_doc_type"] = {
            dt: evaluate_mode(items, best, top_k=top_k)
            for dt, items in sorted(by_type.items())
            if len(items) >= 10
        }
        results["breakdown_mode"] = best
    return results


def render(results: dict) -> None:
    t = Table(title=f"Retrieval ablation ({results.get('queries', 0)} queries)")
    t.add_column("mode")
    for col in ("R@1", "R@5", "R@10", "MRR", "nDCG@10", "median ms", "p95 ms"):
        t.add_column(col, justify="right")
    for mode, m in results.get("modes", {}).items():
        t.add_row(
            mode,
            f"{m['recall@1']:.3f}",
            f"{m['recall@5']:.3f}",
            f"{m['recall@10']:.3f}",
            f"{m['mrr']:.3f}",
            f"{m['ndcg@10']:.3f}",
            f"{m['median_latency_ms']:.0f}",
            f"{m['p95_latency_ms']:.0f}",
        )
    console.print(t)

    if results.get("by_doc_type"):
        t = Table(title=f"By document type — {results.get('breakdown_mode')}")
        t.add_column("doc type")
        for col in ("n", "R@5", "MRR"):
            t.add_column(col, justify="right")
        for dt, m in results["by_doc_type"].items():
            t.add_row(dt, f"{m['n']}", f"{m['recall@5']:.3f}", f"{m['mrr']:.3f}")
        console.print(t)


def evaluate_and_save(path: Path | None = None, **kwargs) -> dict:
    results = evaluate(**kwargs)
    out = path or (settings.artifact_dir / "eval_retrieval.json")
    out.write_text(json.dumps(results, indent=2))
    render(results)
    console.print(f"[green]Wrote {out}[/green]")
    return results
